package paige.navic.domain.manager

import kotlinx.serialization.Serializable
import paige.navic.domain.models.settings.StationCharacter

/*
 * Stations: radio and autoplay generated by the hub (navi-connect PROTOCOL §18, I-040).
 *
 * The wire shapes of `/sonic/station/...`, what this device keeps about the station that built its
 * queue, and every decision the autoplay driver and the queue sheet make about them, as pure
 * functions (`StationDriverTest`). `StationManager` does the HTTP; `RadioManager` acts.
 *
 * Words: in the UI a seeded station is a "radio" and the seedless one "Your mix". "Station" is the
 * noun in code and on the wire only; it already names Subsonic internet radio in this app.
 */

/** Feature name in `welcome.features` (PROTOCOL §3.1) for a hub with the engine. */
const val HUB_FEATURE_STATION = "station"

/** One character as the hub's catalogue words it (`GET /sonic/station/characters`). */
@Serializable
data class StationCharacterInfo(
	val id: String = "",
	val label: String = "",
	val description: String = "",
	val legacy: String = ""
)

/**
 * The probe's answer. Always 200 from a hub with the routes: [configured] false means the engine
 * is off, [available] false that no tier answered its last probe. [engine] is `tier2` (AudioMuse)
 * or `tier1` (Navidrome only), null when neither.
 */
@Serializable
data class StationCatalogue(
	val configured: Boolean = false,
	val available: Boolean = false,
	val engine: String? = null,
	val default: String = StationCharacter.Default.wireId,
	val characters: List<StationCharacterInfo> = emptyList()
) {
	/** The catalogue's words for [character], or the bundled ones. */
	fun infoFor(character: StationCharacter): StationCharacterInfo =
		characters.firstOrNull { it.id == character.wireId }
			?: BUNDLED.characters.first { it.id == character.wireId }

	companion object {
		/**
		 * The catalogue PROTOCOL §18.1 specifies, for a hub that has not answered yet. Never says
		 * available: that is learned from a hub, per process.
		 */
		val BUNDLED = StationCatalogue(
			characters = listOf(
				StationCharacterInfo(
					"close", "Close", "Stays right next to what you started with.", "EchoMatch"
				),
				StationCharacterInfo(
					"balanced", "Balanced", "Near what you started with, with room to move.", "SteadyVibes"
				),
				StationCharacterInfo(
					"explore", "Explore", "Wanders further, steered by what you skip and like.", "TransitionMaestro"
				)
			)
		)
	}
}

/** What a station is seeded from. `track` and `tracks` carry ids (1, or 1–5); `yourMix` none. */
@Serializable
data class StationSeed(
	val kind: String,
	val ids: List<String> = emptyList(),
	val name: String? = null
) {
	companion object {
		const val TRACK = "track"
		const val TRACKS = "tracks"
		const val YOUR_MIX = "yourMix"

		val YourMix = StationSeed(YOUR_MIX)
	}
}

@Serializable
data class StationTrack(
	val id: String = "",
	val title: String = "",
	val artist: String = "",
	val album: String = "",
	val why: String = "",
	val rank: Int? = null
)

/** `start` and `next` answer with this shape; fields one of them lacks are left at their defaults. */
@Serializable
data class StationAnswer(
	val stationId: String = "",
	val name: String = "",
	val character: String = "",
	val engine: String? = null,
	val seed: StationSeed? = null,
	val seq: Int = 0,
	val rev: Int = 0,
	val tracks: List<StationTrack> = emptyList(),
	val exhausted: Boolean = false,
	val partial: Boolean = false,
	val servedElsewhere: Boolean = false
)

@Serializable
internal data class StationStartBody(
	val seed: StationSeed,
	val character: String? = null,
	val count: Int,
	val exclude: List<String>,
	val bindSession: String? = null,
	val deviceId: String? = null
)

@Serializable
internal data class StationNextBody(
	val stationId: String,
	val after: Int,
	val count: Int,
	val exclude: List<String>,
	val deviceId: String? = null
)

@Serializable
internal data class StationSignalBody(
	val stationId: String,
	val trackId: String,
	val kind: String,
	val value: String? = null
)

/** A refusal's body: `{code, stationId}` for 4xx, `{fallback: true}` for 503. */
@Serializable
internal data class StationRefusal(
	val code: String? = null,
	val stationId: String? = null,
	val fallback: Boolean = false
)

/** How one `start` or `next` came back. */
sealed interface StationResult {
	data class Ok(val answer: StationAnswer) : StationResult

	/** 409 `session_bound`: the session already has [stationId]; continue that one with `next`. */
	data class SessionBound(val stationId: String) : StationResult

	/** 404 `station_unknown`: expired, or a hub that lost it. Start again once from the seed. */
	data object StationUnknown : StationResult

	/** 404 `seed_unknown`: AudioMuse holds no such seed track. */
	data object SeedUnknown : StationResult

	/**
	 * No station can be had: 503 `{fallback: true}`, no hub configured, a hub without the
	 * engine, or the hub unreachable. The caller runs its own fallback (Auto DJ, the old radio).
	 */
	data class Unavailable(val reason: String) : StationResult
}

/**
 * The station that built this device's current queue, persisted (`PreferenceManager.
 * stationProvenance`) so a restart keeps it. [queueId] is the saved-queue id of the queue it
 * belongs to (`PlayerUiState.savedQueueId`): a new queue has another id, which is how a new album
 * or playlist stops being "the radio" without anything clearing this.
 *
 * [seq] is the station's cursor as this device last applied it (`after` on the next `next`).
 * [lastFromAutoDj] is true when the newest top-up of this queue came from Auto DJ because the hub
 * could not be had, so the queue sheet says so.
 */
@Serializable
data class StationProvenance(
	val queueId: String,
	val stationId: String,
	val name: String = "",
	val character: String = StationCharacter.Default.wireId,
	val engine: String? = null,
	val seed: StationSeed? = null,
	val seq: Int = 0,
	val rev: Int = 0,
	val exhausted: Boolean = false,
	val lastFromAutoDj: Boolean = false
)

/** The `station` frame and `welcome.station` (PROTOCOL §18.2); [name] / [seed] in welcome only. */
data class HubStationFrame(
	val stationId: String,
	val seq: Int,
	val rev: Int,
	val character: String,
	val exhausted: Boolean,
	val name: String? = null,
	val seed: StationSeed? = null
)

/** A station's provenance after an answer was applied to its queue. */
internal fun StationProvenance.applied(answer: StationAnswer): StationProvenance = copy(
	stationId = answer.stationId.ifBlank { stationId },
	name = answer.name.ifBlank { name },
	character = answer.character.ifBlank { character },
	engine = answer.engine ?: engine,
	seed = answer.seed ?: seed,
	seq = maxOf(seq, answer.seq),
	rev = maxOf(rev, answer.rev),
	exhausted = answer.exhausted,
	lastFromAutoDj = false
)

/** What one `start` / `next` answer does: the record after it, the ids to append, and whether to ask again soon. */
data class StationBatch(
	val provenance: StationProvenance,
	val append: List<String>,
	val retrySoon: Boolean
)

/**
 * Apply [answer] to the queue [bound] belongs to, holding [queued]. Served elsewhere: another
 * device topped the station up (its batch reaches this queue through the session), so only the
 * cursor is taken and nothing is asked again at once. Otherwise the station's new tracks not
 * already queued are appended, and an answer with none that is not `exhausted` (a `partial`
 * one, or every track already queued) is asked again soon. [fresh]: the record of a station
 * just started, whose cursor is the answer's whatever the record held.
 */
fun stationBatch(
	bound: StationProvenance,
	answer: StationAnswer,
	queued: Set<String>,
	fresh: Boolean
): StationBatch {
	if (answer.servedElsewhere) {
		return StationBatch(bound.copy(seq = maxOf(bound.seq, answer.seq)), emptyList(), retrySoon = false)
	}
	val ids = answer.tracks.map { it.id }.filter { it.isNotBlank() && it !in queued }.distinct()
	val applied = bound.applied(answer).let { if (fresh) it.copy(seq = answer.seq, rev = answer.rev) else it }
	return StationBatch(applied, ids, retrySoon = ids.isEmpty() && !answer.exhausted)
}

/** A `station` frame for this provenance's station, laid over it. Frames for another station change nothing. */
internal fun StationProvenance.withFrame(frame: HubStationFrame): StationProvenance =
	if (frame.stationId != stationId) this
	else copy(
		seq = maxOf(seq, frame.seq),
		rev = maxOf(rev, frame.rev),
		character = frame.character.ifBlank { character },
		exhausted = frame.exhausted
	)

// --------------------------------------------------------------------------------------------- //
// Play order
// --------------------------------------------------------------------------------------------- //

/**
 * How many songs are left after the playing one, in the order the player will play them.
 * [order] is the queue indices in play order (the shuffle order), or null for queue order. An
 * order that does not hold [currentIndex] (a timeline mid-change) is read as queue order.
 */
fun playOrderRemaining(order: List<Int>?, queueSize: Int, currentIndex: Int): Int {
	if (queueSize <= 0 || currentIndex < 0) return 0
	if (order != null && order.size == queueSize) {
		val at = order.indexOf(currentIndex)
		if (at >= 0) return order.size - at - 1
	}
	return (queueSize - currentIndex - 1).coerceAtLeast(0)
}

/** Up to [n] queue indices played just before [currentIndex], newest first, then the playing one first. */
fun playOrderRecent(order: List<Int>?, queueSize: Int, currentIndex: Int, n: Int): List<Int> {
	if (queueSize <= 0 || currentIndex !in 0 until queueSize || n <= 0) return emptyList()
	val sequence = if (order != null && order.size == queueSize && currentIndex in order) order
	else (0 until queueSize).toList()
	val at = sequence.indexOf(currentIndex)
	return (at downTo maxOf(0, at - n + 1)).map { sequence[it] }
}

// --------------------------------------------------------------------------------------------- //
// The autoplay driver's decision
// --------------------------------------------------------------------------------------------- //

/** Ask for more when fewer than this many songs are left after the playing one (play order). */
const val STATION_LOOKAHEAD = 2

/** How many songs one `next` asks for: a short lookahead, so skips steer the next batch soon. */
const val STATION_BATCH = 5

/** What autoplay should do for one look at the local player. */
sealed interface AutoplayStep {
	/** Nothing now. */
	data object Idle : AutoplayStep

	/** Continue [stationId] from [after]. */
	data class Next(val stationId: String, val after: Int) : AutoplayStep

	/** The queue is no station's: start one from its last tracks and bind it to the session. */
	data object Start : AutoplayStep

	/** No engine: Auto DJ tops the queue up. */
	data object AutoDj : AutoplayStep

	/** The station has nothing left that fits: autoplay stops, and the queue sheet says so. */
	data object Exhausted : AutoplayStep
}

/** Everything [autoplayStep] decides from, read at one moment. */
data class AutoplayLook(
	val autoplayOn: Boolean,
	/** Another hub device is playing: this device's player is frozen, the playing one tops up. */
	val remoteActive: Boolean,
	val paused: Boolean,
	val repeatMode: Int,
	val queueSize: Int,
	val currentIndex: Int,
	/** Songs left after the playing one, in play order ([playOrderRemaining]). */
	val remaining: Int,
	val stationsAvailable: Boolean,
	/** The station this queue belongs to, if any ([boundStation]). */
	val bound: StationProvenance?,
	/** A `start` / `next` / Auto DJ top-up is already out: one at a time. */
	val inFlight: Boolean,
	val autoDjTiming: Int
)

/**
 * The driver's rule. Local playback only; nothing while paused, repeating (the queue loops or
 * holds) or with a request out. With the engine, a station-bound queue asks `next` when fewer
 * than [STATION_LOOKAHEAD] songs are left and stops for good once the station is exhausted; a
 * queue no station built asks `start` at the same point. Without it, Auto DJ at its own timing.
 */
fun autoplayStep(look: AutoplayLook): AutoplayStep {
	if (!look.autoplayOn || look.remoteActive || look.inFlight) return AutoplayStep.Idle
	if (look.paused || look.repeatMode != 0) return AutoplayStep.Idle
	if (look.queueSize <= 0 || look.currentIndex !in 0 until look.queueSize) return AutoplayStep.Idle
	if (!look.stationsAvailable) {
		return if (autoDjDue(look.remaining, look.autoDjTiming)) AutoplayStep.AutoDj else AutoplayStep.Idle
	}
	if (look.remaining >= STATION_LOOKAHEAD) return AutoplayStep.Idle
	val bound = look.bound ?: return AutoplayStep.Start
	if (bound.exhausted) return AutoplayStep.Exhausted
	return AutoplayStep.Next(bound.stationId, bound.seq)
}

/**
 * The station a queue belongs to. The local record when it is this queue's ([queueId]) and the
 * session does not name another; else, while this device plays the hub session, the session's own
 * station ([sessionStationId], from `session.stationId`, passed only then): a queue handed here by
 * a transfer continues the station it was, from the cursor the hub last broadcast ([frameOf]).
 * A session station this device has no record of keeps no seed, so it cannot be restarted.
 */
fun boundStation(
	provenance: StationProvenance?,
	queueId: String?,
	sessionStationId: String?,
	frameOf: (String) -> HubStationFrame?,
	sessionName: String?
): StationProvenance? {
	if (queueId == null) return null
	if (provenance != null && (provenance.queueId == queueId || provenance.stationId == sessionStationId) &&
		(sessionStationId == null || sessionStationId == provenance.stationId)
	) {
		val mine = provenance.copy(queueId = queueId)
		return frameOf(mine.stationId)?.let { mine.withFrame(it) } ?: mine
	}
	if (sessionStationId == null) return null
	val frame = frameOf(sessionStationId)
	return StationProvenance(
		queueId = queueId,
		stationId = sessionStationId,
		name = frame?.name ?: sessionName.orEmpty(),
		character = frame?.character?.ifBlank { null } ?: StationCharacter.Default.wireId,
		seed = frame?.seed,
		seq = frame?.seq ?: 0,
		rev = frame?.rev ?: 0,
		exhausted = frame?.exhausted ?: false
	)
}

// --------------------------------------------------------------------------------------------- //
// What the queue sheet says built the queue
// --------------------------------------------------------------------------------------------- //

/** The queue sheet's line about what built the queue. Never read from the autoplay preference. */
sealed interface QueueGenerator {
	/** A station: "Cinnamon Girl radio · Balanced", "… · via Navidrome" when Navidrome answered. */
	data class Station(
		val name: String,
		val character: StationCharacter,
		val viaNavidrome: Boolean,
		val yourMix: Boolean
	) : QueueGenerator

	/** The station has nothing left that fits; [offerExplore] when it is not on Explore already. */
	data class Exhausted(val name: String, val offerExplore: Boolean) : QueueGenerator

	/** Auto DJ topped this queue up (no engine, or the hub could not be had for that top-up). */
	data object AutoDj : QueueGenerator

	/** A mix built here without the engine (the old radio, a journey, a mix). */
	data object AudioMuseMix : QueueGenerator
}

/**
 * The line for the current queue. [bound] is the station it belongs to ([boundStation]);
 * [autoDjQueueId] the queue Auto DJ last topped up; [generatedMix] whether the queue is exactly a
 * mix generated here without a station.
 */
fun queueGenerator(
	bound: StationProvenance?,
	queueId: String?,
	autoDjQueueId: String?,
	generatedMix: Boolean
): QueueGenerator? {
	if (bound != null) {
		if (bound.lastFromAutoDj) return QueueGenerator.AutoDj
		val character = StationCharacter.fromWire(bound.character) ?: StationCharacter.Default
		val yourMix = bound.seed?.kind == StationSeed.YOUR_MIX
		if (bound.exhausted) {
			return QueueGenerator.Exhausted(bound.name, offerExplore = character != StationCharacter.Explore)
		}
		return QueueGenerator.Station(
			name = bound.name,
			character = character,
			viaNavidrome = bound.engine == ENGINE_TIER1,
			yourMix = yourMix
		)
	}
	if (queueId != null && queueId == autoDjQueueId) return QueueGenerator.AutoDj
	if (generatedMix) return QueueGenerator.AudioMuseMix
	return null
}

/** `engine` when Navidrome alone answered (AudioMuse down, or not configured on the hub). */
const val ENGINE_TIER1 = "tier1"

// --------------------------------------------------------------------------------------------- //
// Seeds
// --------------------------------------------------------------------------------------------- //

/** Up to [n] items spread evenly over [items], first and last included: an album radio's seed. */
fun <T> spreadPick(items: List<T>, n: Int): List<T> {
	if (n <= 0 || items.isEmpty()) return emptyList()
	if (items.size <= n) return items
	if (n == 1) return listOf(items.first())
	val step = (items.size - 1).toDouble() / (n - 1)
	return (0 until n).map { items[(it * step + 0.5).toInt().coerceAtMost(items.lastIndex)] }.distinct()
}

/** The most an `exclude` list may carry (PROTOCOL §18.1). The newest are kept. */
const val STATION_EXCLUDE_MAX = 1000

fun stationExclude(queueIds: List<String>): List<String> =
	queueIds.distinct().takeLast(STATION_EXCLUDE_MAX)
